PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:investorId ?investorId . }
  OPTIONAL { ?investor wm:investorName ?investorName . }

  ?goal rdf:type wm:InvestmentGoal ;
        wm:progressPct ?progressPct ;
        wm:belongsToInvestor ?investor .
  FILTER ( xsd:decimal(?progressPct) < 20 )

  ?health rdf:type wm:PortfolioHealth ;
          wm:riskScore ?riskScore ;
          wm:healthOfInvestor ?investor .
  FILTER ( xsd:decimal(?riskScore) > 70 )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance ?riskBand (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  {
    SELECT DISTINCT ?investor ?riskTolerance ?riskBand
    WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL { ?investor wm:riskTolerance ?rt . }
      BIND (COALESCE(?rt, "NULL") AS ?riskTolerance) .
      ?investor wm:hasHolding ?holding .
      ?holding rdf:type wm:PortfolioHolding .
      OPTIONAL {
        ?ph rdf:type wm:PortfolioHealth .
        ?ph wm:healthOfInvestor ?investor .
        ?ph wm:riskScore ?riskScore .
      }
      BIND(
        IF(!BOUND(?riskScore), "NULL",
          IF(xsd:decimal(?riskScore) < 20, "Low",
            IF(xsd:decimal(?riskScore) < 40, "Medium",
              IF(xsd:decimal(?riskScore) < 60, "High",
                IF(xsd:decimal(?riskScore) < 80, "Very High", "Extreme")
              )
            )
          )
        ) AS ?riskBand)
    }
  }
}
GROUP BY ?riskTolerance ?riskBand

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }

  OPTIONAL { ?investor wm:segment ?segmentLit . }
  OPTIONAL {
    ?investor wm:hasSegment ?segmentObj .
    ?segmentObj rdfs:label ?segmentLabel .
  }
  BIND(COALESCE(?segmentLit, ?segmentLabel) AS ?segmentValue)
  FILTER(BOUND(?segmentValue) && LCASE(STR(?segmentValue)) = "aggressive")

  ?goal rdf:type wm:InvestmentGoal .
  ?goal wm:belongsToInvestor ?investor .
  ?goal wm:shortfall ?shortfall .
  FILTER(xsd:decimal(?shortfall) > 0)

  FILTER EXISTS {
    {
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
    } UNION {
      ?investor wm:hasHolding ?holding .
    }
    ?holding wm:investmentName ?invName .
    FILTER(CONTAINS(LCASE(STR(?invName)), "gold"))
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolGroup (AVG(?investorAvgProgress) AS ?avgGoalProgress) (AVG(?investorRiskScore) AS ?avgPortfolioRisk)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:riskTolerance ?riskTol . }
  BIND(COALESCE(?riskTol, "NULL") AS ?riskTolGroup)

  # Average progress per investor
  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?investorAvgProgress)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:progressPct ?progressPct .
    }
    GROUP BY ?investor
  }

  # Portfolio risk score per investor
  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?riskScoreVal)) AS ?investorRiskScore)
    WHERE {
      ?ph rdf:type wm:PortfolioHealth .
      ?investor wm:hasPortfolioHealth ?ph .
      ?ph wm:riskScore ?riskScoreVal .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolGroup

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
