PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskGroup (SUM(?hv) AS ?totalHoldingValue) (SUM(?si) AS ?totalSectorAllocationInvestment)
WHERE {
  ?investor rdf:type wm:Investor .

  OPTIONAL {
    ?investor wm:hasRiskTolerance ?rt .
    ?rt rdfs:label ?riskLabel .
  }
  BIND(COALESCE(?riskLabel, "NULL") AS ?riskGroup)

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?cv)) AS ?hv)
    WHERE {
      ?investor wm:hasHolding ?h .
      ?h wm:currentValue ?cv .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?ti)) AS ?si)
    WHERE {
      ?investor wm:hasSectorAllocation ?a .
      ?a wm:totalInvestment ?ti .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskGroup

