PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?totalShortfall ?totalHoldingGain ?netCashFlow WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  {
    SELECT ?investorId (SUM(xsd:decimal(?sf)) AS ?totalShortfall) WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:shortfall ?sf .
      ?goal wm:belongsToInvestor ?invGoal .
      ?invGoal wm:investorId ?investorId .
    } GROUP BY ?investorId
    HAVING (SUM(xsd:decimal(?sf)) > 0)
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?totalHoldingGain) WHERE {
      ?hold rdf:type wm:PortfolioHolding .
      ?hold wm:cost ?cost .
      ?hold wm:currentValue ?curr .
      BIND (xsd:decimal(?curr) - xsd:decimal(?cost) AS ?gain) .
      ?hold wm:heldByInvestor ?invHold .
      ?invHold wm:investorId ?investorId .
    } GROUP BY ?investorId
    HAVING (SUM(xsd:decimal(?gain)) < 0)
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?amt)) AS ?netCashFlow) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:amount ?amt .
      ?cf wm:cashFlowOfInvestor ?invCF .
      ?invCF wm:investorId ?investorId .
    } GROUP BY ?investorId
    HAVING (SUM(xsd:decimal(?amt)) < 10000)
  }
