PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?scenario (AVG(?absChange) AS ?avgAbsChange)
WHERE {
  ?sr rdf:type wm:ScenarioRebalancing ;
      wm:currentAllocationPct ?curr ;
      wm:newAllocationPct ?new ;
      wm:hasMarketScenario ?ms .
  OPTIONAL { ?sr wm:scenario ?scenarioLiteral . }
  OPTIONAL { ?ms rdfs:label ?msLabel . }
  BIND(COALESCE(?scenarioLiteral, ?msLabel, "UNKNOWN") AS ?scenario) .
  FILTER(BOUND(?curr) && BOUND(?new)) .
  BIND(ABS(xsd:decimal(?new) - xsd:decimal(?curr)) AS ?absChange) .
}
GROUP BY ?scenario
ORDER BY DESC(?avgAbsChange)
LIMIT 5

