SELECT ?riskTolerance ?goalBucket (COUNT(?investor) AS ?investorCount)
WHERE {
  {
    SELECT ?investor (COALESCE(?rt, "NULL") AS ?riskTolerance) (COUNT(DISTINCT ?goal) AS ?goalCount)
    WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL { ?investor wm:riskTolerance ?rt . }
      OPTIONAL {
        ?goal rdf:type wm:InvestmentGoal .
        ?goal wm:belongsToInvestor ?investor .
      }
    }
    GROUP BY ?investor ?rt
  }
  BIND(
    IF(?goalCount = 1, "1",
      IF(?goalCount = 2, "2",
        IF(?goalCount = 3, "3", "4+")
      )
    ) AS ?goalBucket
  )
}
GROUP BY ?riskTolerance ?goalBucket
ORDER BY ?riskTolerance ?goalBucket

