SELECT ?investorId ?investorName ?avgProgress ?riskScore ?totalWithdrawal
WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avgProgress)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?invGoal .
      ?invGoal wm:investorId ?investorId .
      ?goal wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (MAX(xsd:decimal(?riskScore)) AS ?riskScore)
    WHERE {
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:healthOfInvestor ?invPh .
      ?invPh wm:investorId ?investorId .
      ?ph wm:riskScore ?riskScore .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?totalWithdrawal)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?invCf .
      ?invCf wm:investorId ?investorId .
      ?cf wm:type ?type .
      FILTER(LCASE(STR(?type)) = "withdrawal")
      ?cf wm:amount ?amount .
    }
    GROUP BY ?investorId
  }

  FILTER(?avgProgress < 40 && ?riskScore > 50)
}
ORDER BY DESC(?totalWithdrawal)
