    ?goalTypeObj2 rdfs:label ?goalTypeObj2Label .
  }
  BIND(COALESCE(?goalTypeLiteral, ?goalTypeObj2Label) AS ?goalTypeLabel)
  FILTER(CONTAINS(LCASE(STR(?goalTypeLabel)), "income generation"))

  # Cash flow (dividend reinvestment)
  ?investor wm:hasCashFlow ?cf .
  ?cf rdf:type wm:CashFlow .
  OPTIONAL { ?cf wm:type ?cfTypeLiteral . }
  OPTIONAL {
    ?cf wm:hasCashFlowType ?cfTypeObj .
    ?cfTypeObj rdfs:label ?cfTypeObjLabel .
  }
  BIND(COALESCE(?cfTypeLiteral, ?cfTypeObjLabel) AS ?cfTypeLabel)
  FILTER(CONTAINS(LCASE(STR(?cfTypeLabel)), "dividend reinvestment"))
}

