SELECT ?riskTol ?rebLogic (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  ?investor rdf:type wm:Investor .

  # Risk tolerance (object label or literal)
  OPTIONAL {
    ?investor wm:hasRiskTolerance ?rt .
    OPTIONAL { ?rt rdfs:label ?rtLabel . }
  }
  OPTIONAL { ?investor wm:riskTolerance ?rtLiteral . }
  BIND(COALESCE(?rtLiteral, ?rtLabel, "NULL") AS ?riskTol)

  # Rebalancing logic (from action literal or linked logic label)
  OPTIONAL {
    ?investor wm:hasRebalancingAction ?ra .
    OPTIONAL { ?ra wm:logic ?logicLiteral . }
    OPTIONAL {
      ?ra wm:hasRebalancingLogic ?rl .
      OPTIONAL { ?rl rdfs:label ?rlLabel . }
    }
    BIND(COALESCE(?logicLiteral, ?rlLabel, "NULL") AS ?rebLogic)
  }

  # Investor must have at least one scenario rebalancing record
  FILTER EXISTS {
    ?scenario rdf:type wm:ScenarioRebalancing .
    ?scenario wm:scenarioRebalancingOfInvestor ?investor .
  }
}
GROUP BY ?riskTol ?rebLogic

