SELECT ?sectorLabel (AVG(xsd:decimal(?invAvgProgress)) AS ?avgGoalProgress) (AVG(xsd:decimal(?invLiquidityScore)) AS ?avgLiquidityScore)
WHERE {
  {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?invAvgProgress) (AVG(xsd:decimal(?liquidityScore)) AS ?invLiquidityScore)
    WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL {
        ?ph rdf:type wm:PortfolioHealth .
        ?ph wm:healthOfInvestor ?investor .
        ?ph wm:liquidityScore ?liquidityScore .
      }
      OPTIONAL {
        ?goal rdf:type wm:InvestmentGoal .
        ?goal wm:belongsToInvestor ?investor .
        ?goal wm:progressPct ?progressPct .
      }
    }
    GROUP BY ?investor
  }
  {
    SELECT DISTINCT ?investor ?sectorLabel WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:hasHolding ?holding .
      ?holding wm:hasSector ?sector .
      OPTIONAL { ?sector rdfs:label ?sectorLabel . }
    }
  }
  FILTER(BOUND(?sectorLabel))
}
GROUP BY ?sectorLabel

