  {
    SELECT ?cat ?categoryLabel (AVG(xsd:decimal(?allocPct)) AS ?avgAllocationPct)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:hasCategory ?cat .
      OPTIONAL { ?cat rdfs:label ?categoryLabel . }
      ?investor wm:hasRebalancingAction ?reb .
      ?reb wm:currentAllocationPct ?allocPct .
    }
    GROUP BY ?cat ?categoryLabel
  }
  {
    SELECT ?cat (AVG(xsd:decimal(?returnsPct)) AS ?avgHoldingReturnPct)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:hasCategory ?cat .
      ?investor wm:hasHolding ?hold .
      ?hold wm:returnsPct ?returnsPct .
    }
    GROUP BY ?cat
  }
}

