      OPTIONAL {
        ?cf wm:hasCashFlowType ?typeObj .
        ?typeObj rdfs:label ?typeLabel .
      }
      OPTIONAL {
        ?cf wm:type ?typeLiteral .
      }
      BIND (COALESCE(?typeLabel, ?typeLiteral, "NULL") AS ?cashFlowType)
    }
  }
}
GROUP BY ?cashFlowType

