SELECT ?category ?deposit_amount ?withdrawal_amount WHERE {
  {
    SELECT ?category (SUM(xsd:decimal(?amt)) AS ?deposit_amount) WHERE {
      ?inv rdf:type wm:Investor .
      ?inv wm:category ?category .
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?inv .
      ?cf wm:type ?type .
      FILTER(CONTAINS(LCASE(STR(?type)), "deposit"))
      ?cf wm:amount ?amt .
    } GROUP BY ?category
  }
  OPTIONAL {
    SELECT ?category (SUM(xsd:decimal(?amt)) AS ?withdrawSum) WHERE {
      ?inv rdf:type wm:Investor .
      ?inv wm:category ?category .
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?inv .
      ?cf wm:type ?type .
      FILTER(CONTAINS(LCASE(STR(?type)), "withdrawal"))
      ?cf wm:amount ?amt .
    } GROUP BY ?category
  }
  BIND( IF(BOUND(?withdrawSum), -?withdrawSum, 0) AS ?withdrawal_amount )
}

