PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:investorId ?investorId . }
  OPTIONAL { ?investor wm:investorName ?investorName . }

  ?goal rdf:type wm:InvestmentGoal ;
        wm:belongsToInvestor ?investor ;
        wm:progressPct ?progressPct .

  ?health rdf:type wm:PortfolioHealth ;
          wm:healthOfInvestor ?investor ;
          wm:liquidityScore ?liquidityScore .

  FILTER ( xsd:decimal(?progressPct) < 25 )
  FILTER ( xsd:decimal(?liquidityScore) < 30 )
}

