PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?source (COUNT(?cf) AS ?transactionCount) (SUM(xsd:decimal(?amount)) AS ?netAmount)
WHERE {
  ?cf rdf:type wm:CashFlow .
  OPTIONAL { ?cf wm:source ?sourceLiteral . }
  OPTIONAL {
    ?cf wm:hasCashFlowSource ?sourceObj .
    OPTIONAL { ?sourceObj rdfs:label ?sourceLabel . }
    OPTIONAL { ?sourceObj wm:source ?sourceObjLiteral . }
  }
  BIND(COALESCE(?sourceLabel, ?sourceObjLiteral, ?sourceLiteral, "NULL") AS ?source)
  ?cf wm:amount ?amount .
}
GROUP BY ?source

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COALESCE(?logic, "NULL") AS ?logic) (COUNT(?ra) AS ?actionCount) (SUM(?amt) AS ?totalAmount)
WHERE {
  {
    SELECT ?ra ?logic ?amt WHERE {
      ?ra rdf:type wm:RebalancingAction .
      OPTIONAL { ?ra wm:logic ?logic . }
      OPTIONAL {
        ?ra wm:amount ?rawAmt .
        BIND(xsd:decimal(?rawAmt) AS ?amt)
      }
    }
  }
}
GROUP BY ?logic

