PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?scenario
       ?avgCurrentAllocationPct
       ?avgNewAllocationPct
       ((?avgCurrentAllocationPct - ?avgNewAllocationPct) AS ?difference)
WHERE {
  {
    SELECT ?scenario
           (AVG(xsd:decimal(?currentAllocationPct)) AS ?avgCurrentAllocationPct)
           (AVG(xsd:decimal(?newAllocationPct)) AS ?avgNewAllocationPct)
    WHERE {
      ?sr rdf:type wm:ScenarioRebalancing .
      OPTIONAL { ?sr wm:scenario ?scenario . }
      OPTIONAL { ?sr wm:currentAllocationPct ?currentAllocationPct . }
      OPTIONAL { ?sr wm:newAllocationPct ?newAllocationPct . }
      FILTER(BOUND(?scenario) && BOUND(?currentAllocationPct) && BOUND(?newAllocationPct))
    }
    GROUP BY ?scenario
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }

  FILTER EXISTS {
    ?investor wm:hasCashFlow ?cf .
    ?cf wm:hasCashFlowType ?cft .
    ?cft rdfs:label ?cftLabel .
    FILTER(LCASE(STR(?cftLabel)) = "withdrawal")
  }

  FILTER EXISTS {
    ?investor wm:hasInvestmentGoal ?goal .
    ?goal wm:timeToGoalMonths ?months .
    FILTER(xsd:decimal(?months) <= 12)
  }

  FILTER EXISTS {
    ?investor wm:hasRebalancingAction ?reb .
    ?reb wm:action ?rebAction .
    FILTER(LCASE(STR(?rebAction)) = "sell")
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?logic ?triggered (COUNT(DISTINCT ?inv) AS ?investorCount)
WHERE {
  ?inv rdf:type wm:Investor .
  ?ra rdf:type wm:RebalancingAction ;
      wm:logic ?logic ;
      wm:rebalancingActionOfInvestor ?inv .
  ?sr rdf:type wm:ScenarioRebalancing ;
      wm:triggeredAction ?triggered ;
      wm:scenarioRebalancingOfInvestor ?inv .
}
GROUP BY ?logic ?triggered

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?score WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?amt)) AS ?cash2025) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?invCf .
      ?invCf wm:investorId ?investorId .
      ?cf wm:amount ?amt .
      ?cf wm:date ?date .
      FILTER(STRSTARTS(?date, "2025"))
    } GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?rebAmt)) AS ?rebalanceTotal) WHERE {
      ?ra rdf:type wm:RebalancingAction .
      ?ra wm:rebalancingActionOfInvestor ?invRa .
      ?invRa wm:investorId ?investorId .
      ?ra wm:amount ?rebAmt .
    } GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?sf)) AS ?shortfallTotal) WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?invGoal .
      ?invGoal wm:investorId ?investorId .
      ?goal wm:shortfall ?sf .
    } GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?new) - xsd:decimal(?curr)) AS ?scenarioChangeTotal) WHERE {
      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:scenarioRebalancingOfInvestor ?invSr .
      ?invSr wm:investorId ?investorId .
      ?sr wm:newAllocationPct ?new .
      ?sr wm:currentAllocationPct ?curr .
    } GROUP BY ?investorId
  }

  BIND(
    COALESCE(?cash2025, 0) +
    COALESCE(?rebalanceTotal, 0) -
    COALESCE(?shortfallTotal, 0) +
    COALESCE(?scenarioChangeTotal, 0) AS ?score
  )
}
ORDER BY DESC(?score)
LIMIT 10

