PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investmentType
       (SUM(xsd:decimal(?currentValue)) AS ?totalCurrentValue)
       (AVG(xsd:decimal(?returnsPct)) AS ?avgReturnsPct)
       (SUM(xsd:decimal(?dividends)) AS ?totalDividends)
WHERE {
  ?holding rdf:type wm:PortfolioHolding .

  OPTIONAL { ?holding wm:currentValue ?currentValue . }
  OPTIONAL { ?holding wm:returnsPct ?returnsPct . }
  OPTIONAL { ?holding wm:dividends ?dividends . }

  OPTIONAL { ?holding wm:investmentType ?invTypeLiteral . }
  OPTIONAL {
    ?holding wm:hasInvestmentType ?invTypeObj .
    OPTIONAL { ?invTypeObj rdfs:label ?invTypeLabel . }
  }

  BIND( COALESCE(?invTypeLiteral, ?invTypeLabel, "NULL") AS ?investmentType )
}
GROUP BY ?investmentType

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(?invAvgAmount) AS ?avgRebalancingAmount)
       (AVG(?invAvgGap) AS ?avgRebalancingGap)
WHERE {
  # Investor and risk tolerance
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:riskTolerance ?rtLiteral . }
  OPTIONAL {
    ?investor wm:hasRiskTolerance ?rtObj .
    ?rtObj rdfs:label ?rtLabel .
  }
  BIND(COALESCE(?rtLiteral, ?rtLabel, "NULL") AS ?riskTolerance)

  # Aggregate RebalancingAction amount per investor
  {
    SELECT ?investor (AVG(xsd:decimal(?amount)) AS ?invAvgAmount)
    WHERE {
      ?rebalance rdf:type wm:RebalancingAction .
      ?rebalance wm:rebalancingActionOfInvestor ?investor .
      ?rebalance wm:amount ?amount .
    }
    GROUP BY ?investor
  }

  # Aggregate ScenarioRebalancing gap per investor
  OPTIONAL {
    {
      SELECT ?investor (AVG(xsd:decimal(?gap)) AS ?invAvgGap)
      WHERE {
        ?scenario rdf:type wm:ScenarioRebalancing .
        ?scenario wm:scenarioRebalancingOfInvestor ?investor .
        ?scenario wm:newAllocationPct ?newAlloc .
        ?scenario wm:currentAllocationPct ?currAlloc .
        BIND( (xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?gap )
      }
      GROUP BY ?investor
    }
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon ?avgScenarioChange ?avgRebalancingChange WHERE {
  {
    SELECT ?timeHorizon (AVG(?scenarioDiff) AS ?avgScenarioChange) WHERE {
      ?inv rdf:type wm:Investor .
      OPTIONAL { ?inv wm:timeHorizon ?timeHorizon . }
      ?inv wm:investorId ?invId .
      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:investorId ?invId .
      ?sr wm:currentAllocationPct ?currPct .
      ?sr wm:newAllocationPct ?newPct .
      BIND( (xsd:decimal(?newPct) - xsd:decimal(?currPct)) AS ?scenarioDiff )
    }
    GROUP BY ?timeHorizon
  }
  OPTIONAL {
    SELECT ?timeHorizon (AVG(?rebalanceDiff) AS ?avgRebalancingChange) WHERE {
      ?inv rdf:type wm:Investor .
      OPTIONAL { ?inv wm:timeHorizon ?timeHorizon . }
      ?inv wm:investorId ?invId .
      ?ra rdf:type wm:RebalancingAction .
      ?ra wm:investorId ?invId .
      ?ra wm:currentAllocationPct ?currPctRA .
      ?ra wm:targetAllocationPct ?targetPctRA .
      BIND( (xsd:decimal(?targetPctRA) - xsd:decimal(?currPctRA)) AS ?rebalanceDiff )
    }
    GROUP BY ?timeHorizon
  }
}
ORDER BY ?timeHorizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investmentTypeLabel 
       (AVG(xsd:decimal(?liq)) AS ?avgLiquidityScore) 
       (AVG(xsd:decimal(?risk)) AS ?avgRiskScore) 
       (AVG(xsd:decimal(?div)) AS ?avgDiversificationScore)
WHERE {
  {
    SELECT ?investor ?liq ?risk ?div
    WHERE {
      ?health rdf:type wm:PortfolioHealth .
      ?health wm:healthOfInvestor ?investor .
      OPTIONAL { ?health wm:liquidityScore ?liq . }
      OPTIONAL { ?health wm:riskScore ?risk . }
      OPTIONAL { ?health wm:diversificationScore ?div . }
    }
  }
  ?holding rdf:type wm:PortfolioHolding .
  ?holding wm:hasInvestmentType ?invType .
  ?invType rdfs:label ?investmentTypeLabel .
  ?holding wm:heldByInvestor ?investor .
}
GROUP BY ?investmentTypeLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?typeLabel (SUM(xsd:decimal(?rebAmount)) AS ?totalRebalanceAmount) (AVG(xsd:decimal(?rebAmount)) AS ?avgRebalanceAmount) (COUNT(DISTINCT ?invId) AS ?investorCount)
WHERE {
  {
    SELECT ?invId (SUM(xsd:decimal(?raAmount)) AS ?rebAmount) WHERE {
      ?ra rdf:type wm:RebalancingAction .
      ?ra wm:investorId ?invId .
      ?ra wm:amount ?raAmount .
    } GROUP BY ?invId
  }
  {
    SELECT DISTINCT ?invId ?typeLabel WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:investorId ?invId .
      ?cf wm:type ?typeLabel .
    }
  }
}
GROUP BY ?typeLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?logic ?scenario ?avgTarget ?avgScenarioChange ((?avgScenarioChange) - (?avgTarget) AS ?diff)
WHERE {
  {
    SELECT ?logic (AVG(xsd:decimal(?targetAllocationPct)) AS ?avgTarget)
    WHERE {
      ?ra rdf:type wm:RebalancingAction .
      ?ra wm:logic ?logic .
      ?ra wm:targetAllocationPct ?targetAllocationPct .
    }
    GROUP BY ?logic
  }
  {
    SELECT ?scenario (AVG(xsd:decimal(?newAllocationPct) - xsd:decimal(?currentAllocationPct)) AS ?avgScenarioChange)
    WHERE {
      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:scenario ?scenario .
      ?sr wm:newAllocationPct ?newAllocationPct .
      ?sr wm:currentAllocationPct ?currentAllocationPct .
    }
    GROUP BY ?scenario
  }
}
ORDER BY ?logic ?scenario

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sectorLabel ?avgAllocationPct ?avgReturnPct
WHERE {
  {
    SELECT ?sector (AVG(xsd:decimal(?allocationPct)) AS ?avgAllocationPct)
    WHERE {
      ?alloc rdf:type wm:SectorAllocation .
      ?alloc wm:allocationPct ?allocationPct .
      ?alloc wm:hasSector ?sector .
    }
    GROUP BY ?sector
  }
  {
    SELECT ?sector (AVG(xsd:decimal(?returnsPct)) AS ?avgReturnPct)
    WHERE {
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:returnsPct ?returnsPct .
      ?holding wm:hasSector ?sector .
    }
    GROUP BY ?sector
  }
  OPTIONAL { ?sector rdfs:label ?sectorLabel . }
}
ORDER BY ?sectorLabel

