SELECT ?source (AVG(xsd:decimal(?change)) AS ?avgScenarioChange) (SUM(xsd:decimal(?totalCash)) AS ?totalCashAmount)
WHERE {
  {
    SELECT ?investorId ?source (SUM(xsd:decimal(?amount)) AS ?totalCash)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:investorId ?investorId .
      ?cf wm:source ?source .
      OPTIONAL { ?cf wm:amount ?amount . }
    }
    GROUP BY ?investorId ?source
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?delta)) AS ?change)
    WHERE {
      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:investorId ?investorId .
      ?sr wm:currentAllocationPct ?curr .
      ?sr wm:newAllocationPct ?new .
      BIND((xsd:decimal(?new) - xsd:decimal(?curr)) AS ?delta)
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?source

