PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment
       (COALESCE(?totalRebalAmt, xsd:decimal(0)) AS ?totalRebalancingAmount)
       (COALESCE(?totalCashAmt, xsd:decimal(0)) AS ?totalCashFlowAmount)
       (COALESCE(?rebalCount, 0) + COALESCE(?cashCount, 0) AS ?transactionCount)
WHERE {
