PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon
       (AVG(xsd:decimal(?goalProgress)) AS ?avgGoalProgressPct)
       (AVG(xsd:decimal(?holdingReturn)) AS ?avgHoldingReturnPct)
       (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
       (AVG(xsd:decimal(?liquidityScore)) AS ?avgLiquidityScore)
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:timeHorizon ?timeHorizon .

  # Goal progress per investor
  {
    SELECT ?investor (AVG(xsd:decimal(?progress)) AS ?goalProgress)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:progressPct ?progress .
    }
    GROUP BY ?investor
  }

  # Holding return per investor
  {
    SELECT ?investor (AVG(xsd:decimal(?returns)) AS ?holdingReturn)
    WHERE {
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      ?holding wm:returnsPct ?returns .
    }
    GROUP BY ?investor
  }

  # Portfolio health per investor
  {
    SELECT ?investor (AVG(xsd:decimal(?risk)) AS ?riskScore)
                     (AVG(xsd:decimal(?liq)) AS ?liquidityScore)
    WHERE {
      ?health rdf:type wm:PortfolioHealth .
      ?health wm:healthOfInvestor ?investor .
      ?health wm:riskScore ?risk .
      ?health wm:liquidityScore ?liq .
    }
    GROUP BY ?investor
  }
}
