PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon
       (SUM(?rebalanceAmt) AS ?totalRebalanceAmount)
       (SUM(?cashAmt) AS ?totalCashFlow)
       (AVG(?goalProgress) AS ?avgGoalProgress)
       (AVG(?goalShortfall) AS ?avgShortfall)
WHERE {
  ?investor rdf:type wm:Investor .

  # Resolve time horizon (object reference preferred, fallback to literal)
  OPTIONAL {
    ?investor wm:hasTimeHorizon ?th .
    ?th rdfs:label ?thLabel .
    BIND(?thLabel AS ?timeHorizonRaw)
  }
  OPTIONAL {
    ?investor wm:timeHorizon ?thLit .
    BIND(?thLit AS ?timeHorizonRaw)
  }
  BIND(COALESCE(?timeHorizonRaw, "NULL") AS ?timeHorizon)

  # Rebalancing amount per investor
  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?ra)) AS ?rebalanceAmt) WHERE {
      ?rebAction rdf:type wm:RebalancingAction ;
                 wm:rebalancingActionOfInvestor ?investor ;
                 wm:amount ?ra .
    } GROUP BY ?investor
  }

  # Cash flow amount per investor
  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?ca)) AS ?cashAmt) WHERE {
      ?cashFlow rdf:type wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?ca .
    } GROUP BY ?investor
  }

  # Goal progress and shortfall per investor
  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?gp)) AS ?goalProgress) (AVG(xsd:decimal(?sf)) AS ?goalShortfall) WHERE {
      ?goal rdf:type wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?gp ;
            wm:shortfall ?sf .
    } GROUP BY ?investor
  }
}
GROUP BY ?timeHorizon

