PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon
       (AVG(?scenarioChange) AS ?avgScenarioChange)
       (AVG(?rebalancingGap) AS ?avgRebalancingGap)
       (AVG(?riskScore) AS ?avgHealthRisk)
       (AVG(?goalMatchPct) AS ?avgGoalMatch)
WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:timeHorizon ?timeHorizon .

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?diff)) AS ?scenarioChange) WHERE {
      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:scenarioRebalancingOfInvestor ?inv .
      ?sr wm:currentAllocationPct ?cur .
      ?sr wm:newAllocationPct ?new .
      BIND( (xsd:decimal(?new) - xsd:decimal(?cur)) AS ?diff )
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?gap)) AS ?rebalancingGap) WHERE {
      ?ra rdf:type wm:RebalancingAction .
      ?ra wm:rebalancingActionOfInvestor ?inv .
      ?ra wm:currentAllocationPct ?c .
      ?ra wm:targetAllocationPct ?t .
      BIND( (xsd:decimal(?t) - xsd:decimal(?c)) AS ?gap )
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?risk)) AS ?riskScore) (AVG(xsd:decimal(?goal)) AS ?goalMatchPct) WHERE {
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:healthOfInvestor ?inv .
      ?ph wm:riskScore ?risk .
      ?ph wm:goalMatchPct ?goal .
    } GROUP BY ?inv
  }
}
GROUP BY ?timeHorizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon
       (COALESCE(SUM(?cashFlowAmt), 0) AS ?totalCashFlow)
       (COALESCE(SUM(?scenarioCnt), 0) AS ?totalScenarioChanges)
       (COALESCE(AVG(?maxAllocPct), 0) AS ?avgMaxAllocationPct)
       (COALESCE(SUM(?sectorInvestAmt), 0) AS ?totalSectorInvestment)
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:timeHorizon ?timeHorizon .

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?amt)) AS ?cashFlowAmt)
    WHERE {
      ?investor wm:hasCashFlow ?cf .
      ?cf wm:amount ?amt .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (COUNT(?sr) AS ?scenarioCnt)
    WHERE {
      ?investor wm:hasScenarioRebalancing ?sr .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (MAX(xsd:decimal(?allocPct)) AS ?maxAllocPct)
    WHERE {
      ?investor wm:hasSectorAllocation ?sa .
      ?sa wm:allocationPct ?allocPct .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?totalInv)) AS ?sectorInvestAmt)
    WHERE {
      ?investor wm:hasSectorAllocation ?sa2 .
      ?sa2 wm:totalInvestment ?totalInv .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?timeHorizon
ORDER BY ?timeHorizon

