PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon
       (SUM(?cfAmt) AS ?totalCashFlow)
       (SUM(?raAmt) AS ?totalRebalancing)
       (SUM(?scenarioCnt) AS ?scenarioChanges)
       (AVG(?riskScore) AS ?avgRiskScore)
       (AVG(?goalMatchPct) AS ?avgGoalMatchPct)
WHERE {
  ?inv rdf:type wm:Investor ;
       wm:timeHorizon ?timeHorizon .

  # Cash flow per investor
  {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?cfAmt)
    WHERE {
      ?cf rdf:type wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:amount ?amt .
    }
    GROUP BY ?inv
  }

  # Rebalancing amount per investor
  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?raAmt)
    WHERE {
      ?ra rdf:type wm:RebalancingAction ;
          wm:rebalancingActionOfInvestor ?inv ;
          wm:amount ?amt .
    }
    GROUP BY ?inv
  }

  # Scenario change count per investor
  OPTIONAL {
    SELECT ?inv (COUNT(?sc) AS ?scenarioCnt)
    WHERE {
      ?sr rdf:type wm:ScenarioRebalancing ;
          wm:scenarioRebalancingOfInvestor ?inv ;
          wm:scenario ?sc .
    }
    GROUP BY ?inv
  }

  # Portfolio health metrics per investor
  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?rs)) AS ?riskScore) (AVG(xsd:decimal(?gm)) AS ?goalMatchPct)
    WHERE {
      ?ph rdf:type wm:PortfolioHealth ;
          wm:healthOfInvestor ?inv ;
          wm:riskScore ?rs ;
          wm:goalMatchPct ?gm .
    }
    GROUP BY ?inv
  }
}
GROUP BY ?timeHorizon

