PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon
       (SUM(?inflow) AS ?totalInflow)
       (SUM(?outflow) AS ?totalOutflow)
       (SUM(?shortfall) AS ?totalGoalShortfall)
       (SUM(?dividends) AS ?totalDividends)
       (SUM(?taxes) AS ?totalTaxesPaid)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:timeHorizon ?timeHorizon . }

  # Cash‑flow aggregates per investor
  OPTIONAL {
    SELECT ?investor (SUM(?inAmt) AS ?inflow) (SUM(?outAmt) AS ?outflow) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      OPTIONAL { ?cf wm:amount ?amt . }
      OPTIONAL { ?cf wm:type ?cfType . }
      BIND( IF( BOUND(?cfType) && CONTAINS(LCASE(STR(?cfType)), "inflow") && BOUND(?amt),
                xsd:decimal(?amt), 0) AS ?inAmt )
      BIND( IF( BOUND(?cfType) && CONTAINS(LCASE(STR(?cfType)), "outflow") && BOUND(?amt),
                xsd:decimal(?amt), 0) AS ?outAmt )
    } GROUP BY ?investor
  }

  # Investment‑goal shortfall per investor
  OPTIONAL {
    SELECT ?investor (SUM(?sf) AS ?shortfall) WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      OPTIONAL { ?goal wm:shortfall ?sfRaw . }
      BIND( IF(BOUND(?sfRaw), xsd:decimal(?sfRaw), 0) AS ?sf )
    } GROUP BY ?investor
  }

  # Holding dividends and taxes per investor
  OPTIONAL {
    SELECT ?investor (SUM(?div) AS ?dividends) (SUM(?tax) AS ?taxes) WHERE {
      ?hold rdf:type wm:PortfolioHolding .
      ?hold wm:heldByInvestor ?investor .
      OPTIONAL { ?hold wm:dividends ?divRaw . }
      OPTIONAL { ?hold wm:taxesPaid ?taxRaw . }
      BIND( IF(BOUND(?divRaw), xsd:decimal(?divRaw), 0) AS ?div )
      BIND( IF(BOUND(?taxRaw), xsd:decimal(?taxRaw), 0) AS ?tax )
    } GROUP BY ?investor
  }
}
