    SELECT ?investorId (SUM(xsd:decimal(?riskScore)) AS ?riskScoreSum) (SUM(xsd:decimal(?liquidityScore)) AS ?liquidityScoreSum)
    WHERE {
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:investorId ?investorId .
      OPTIONAL { ?ph wm:riskScore ?riskScore . }
